weak_protocol_value(value) {
    some n
    walk(value, [_, n])
    n.ir_type == "String"
    regex.match("(?i)^(?:ssl\\s*v?2|ssl\\s*v?3|tls\\s*v?1\\.0|tls\\s*v?1\\.1|v?1\\.0|v?1\\.1|1\\.0|1\\.1|legacy)$", n.value)
}
